sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    // Read the client state flag
    const clicked = api.state.buttonClicked;

    // Return true to disable button while processing, false otherwise
    return clicked;
}
